window.__SEARCH=[{"t": "Mornfrost Achievements", "u": "/work/mcmod/achievements/", "d": "三百多条成就，正经的和不正经的都有。想给服务器找点事做的时候，它挺合适；一个人慢慢清也能玩上一阵。"}, {"t": "SoulGlyph 灵铭", "u": "/work/mcmod/soulglyph/", "d": "把铭文塞进饰品栏的点子。42 条基础铭文两两融合，能凑出九百多种组合，戴上就生效。后来还做了个节奏更慢的养老版。"}, {"t": "Soulbound Blades 缚魂之刃", "u": "/work/mcmod/soulbound/", "d": "二十把剑，每把都得先解谜、再试炼，最后才长成它该有的样子。数值和文案都写在 JSON 里，改起来不用重开游戏。"}, {"t": "Arsenal", "u": "/work/mcmod/arsenal/", "d": "中式、日式、西式的兵器被放在同一张工作台上：六种矿物、二十九类武器、七十二件护甲，从挖矿到锻造一条线走完。"}, {"t": "Echoes of the Unbound · 未缚回响", "u": "/work/mcmod/echoes/", "d": "五个破碎的维度，四个同行的人。故事从告别开始，每次有人死去，镜头都会停一下。"}, {"t": "Forge of Ascension", "u": "/work/mcmod/ascension/", "d": "两件同等级的装备丢进强化台，合成一件更强的。等级越高越容易碎，失败就什么都不剩——赌的就是这一下。"}, {"t": "中国人能飞", "u": "/work/mcmod/chinesecanfly/", "d": "游戏语言是中文就能飞，切回英文马上掉下来。一个纯粹为了好玩写的模组，没想到还挺多人喜欢。"}, {"t": "Ymondf · 月神", "u": "/work/mcmod/ymondf/", "d": "叙事冒险，「九加一」ARG 的第一个质点。睡一觉会收到一个档案袋，按里面的页走；再往后是月神和它的月相竞技场。0.3 里"}, {"t": "MemoryMaster", "u": "/work/mcmod/memorymaster/", "d": "给服务端省内存的。七个模块能单独关，注入失败会自动退回原版行为，慌了还有一条 /mmcmf panic 兜底。"}, {"t": "BanItemBlock", "u": "/work/mcmod/banitemblock/", "d": "不想让某个方块或物品出现在服务器里，把名字写进配置就行。方块和物品分开列，互不影响。"}, {"t": "Enchantment Remover", "u": "/work/mcmod/enchantremover/", "d": "删掉不想要的附魔。附魔台里刷不出来，战利品和交易里也不会出现，装备上已经有的直接失效。"}, {"t": "Per-Dimension Respawn", "u": "/work/mcmod/perdimrespawn/", "d": "原版只有一个出生点，在地狱放个重生锚就把主世界的床盖掉了。这个模组让每个维度各记各的，死在哪就回哪。"}, {"t": "Login Mod", "u": "/work/mcmod/loginmod/", "d": "服务端的登录注册。没登录之前人被冻住、看不见、点不了东西，安安静静把密码输完。"}, {"t": "KIPL · Kill Inspector", "u": "/work/mcmod/kipl/", "d": "想知道谁杀了谁。输入 /kipl，它会告诉你最近一次击杀的时间、地点，以及是游戏事件还是控制台日志抓到的。"}, {"t": "OreGuard", "u": "/work/mcmod/oreguard/", "d": "反矿透，纯服务端，客户端什么都不用装。除了藏矿，还会看挖掘行为有没有不对劲。"}, {"t": "Let Me Look Look You", "u": "/work/mcmod/lmlly/", "d": "管理员工具：看一眼某个玩家的末影箱、背包或饰品栏。窗口是只读的，拿不出也放不进。"}, {"t": "DeletePortal", "u": "/work/mcmod/deleteportal/", "d": "Danny's AoT 的附属：世界生成时把帕拉迪岛的传送门直接换成空气，顺手数一下清掉了多少。"}, {"t": "FactionZones", "u": "/work/mcmod/factionzones/", "d": "给 Jake's Economy 加的阵营商店分区：每个阵营只看得到自己的货架，外加一个所有人共享的公开商店。"}, {"t": "SQDCLib", "u": "/work/mcmod/sqdclib/", "d": "写叙事模组时反复要的那几件事：状态存档、任务推进、对话分支、演出播放。抽出来做成前置库，四个模块互不依赖，只用一两个也行"}, {"t": "Fix sodium ShaderLoader", "u": "/work/mcmod/fixsodium/", "d": "Sodium 在 NeoForge 上让 nvidium 和 voxy 加载不了着色器，这个补丁先把问题解决掉。修法已经"}, {"t": "小游戏", "u": "/more/games/", "d": "更多 · 小游戏"}, {"t": "扫雷", "u": "/more/games/minesweeper/", "d": "9×9、10 颗雷。左键翻开，右键插旗。"}, {"t": "2048", "u": "/more/games/g2048/", "d": "方向键合并数字，目标是 2048。"}, {"t": "贪吃蛇", "u": "/more/games/snake/", "d": "吃经验球变长，别撞墙也别撞自己。"}, {"t": "俄罗斯方块", "u": "/more/games/tetris/", "d": "消行即破坏，方块越堆越高。"}, {"t": "打砖块", "u": "/more/games/breakout/", "d": "雪球弹射，清空所有矿石砖。"}, {"t": "记忆翻牌", "u": "/more/games/memory/", "d": "十六张牌，八对图标，限时挑战。"}, {"t": "拼图", "u": "/more/games/slidepuzzle/", "d": "3×3 华容道式滑块，按顺序复原。"}, {"t": "挖矿点击器", "u": "/more/games/clicker/", "d": "点方块攒挖掘数，记录存在本地。"}, {"t": "五子棋", "u": "/more/games/gomoku/", "d": "15×15 同屏双人，五连即胜。"}, {"t": "井字棋", "u": "/more/games/tictactoe/", "d": "三连即胜，对手是一个简单 AI。"}, {"t": "石头剪刀布", "u": "/more/games/rps/", "d": "三局两胜，带胜率统计。"}, {"t": "24 点", "u": "/more/games/twentyfour/", "d": "四个数字凑 24，输入算式验证。"}, {"t": "数独", "u": "/more/games/sudoku/", "d": "三档难度，内置题库。"}, {"t": "华容道", "u": "/more/games/klotski/", "d": "移动方块，把目标块移到底部出口。"}, {"t": "推箱子", "u": "/more/games/sokoban/", "d": "把箱子推到目标点，内置三关。"}, {"t": "迷宫", "u": "/more/games/maze/", "d": "程序生成的迷宫，走到出口计时。"}, {"t": "打字游戏", "u": "/more/games/typing/", "d": "打模组名，统计 WPM 与准确率。"}, {"t": "音游", "u": "/more/games/rhythm/", "d": "四键下落，用 WebAudio 合成节拍。"}, {"t": "反应测试", "u": "/more/games/reaction/", "d": "灯亮就点，测你的毫秒数。"}, {"t": "猜数字", "u": "/more/games/guessnumber/", "d": "1–100，八次机会，带提示。"}, {"t": "猜模组", "u": "/more/games/guessmod/", "d": "给一段介绍，猜是哪个模组。"}, {"t": "猜合成表", "u": "/more/games/guessrecipe/", "d": "给成品猜材料，四选一。"}, {"t": "冷知识问答", "u": "/more/games/trivia/", "d": "十道 Minecraft 冷知识，看看能对几道。"}, {"t": "弹幕躲避", "u": "/more/games/dodger/", "d": "移动躲开弹幕，坚持得越久分越高。"}, {"t": "虚空跳跃", "u": "/more/games/voidjump/", "d": "从虚空往上跳，404 页也嵌了一个。"}, {"t": "连连看", "u": "/more/games/lianliankan/", "d": "找出两个相同图标，路径不超过两次转弯。"}, {"t": "三消", "u": "/more/games/match3/", "d": "交换相邻方块，三连即可消除。"}, {"t": "黑白棋", "u": "/more/games/reversi/", "d": "夹住对方棋子即可翻转，最后棋子多者胜。"}, {"t": "跳棋", "u": "/more/games/checkers/", "d": "斜走一步，跳过对方棋子吃掉它。"}, {"t": "数织", "u": "/more/games/nonogram/", "d": "按行列数字涂格，还原图案。"}, {"t": "数回", "u": "/more/games/slitherlink/", "d": "按数字连线，围成单一闭环。"}, {"t": "种子迷宫", "u": "/more/games/mazeseed/", "d": "用一串种子生成同一座迷宫，可分享。"}, {"t": "六边形扫雷", "u": "/more/games/hexmine/", "d": "六方向的扫雷，规则相同但空间更绕。"}, {"t": "2048 · 5×5", "u": "/more/games/g2048x5/", "d": "更大的棋盘，更长的合并链。"}, {"t": "双人贪吃蛇", "u": "/more/games/twosnake/", "d": "同屏两条蛇，撞到对方就输。"}, {"t": "打字防御", "u": "/more/games/typedefense/", "d": "怪从上方落下，打对单词消灭它。"}, {"t": "节奏点击", "u": "/more/games/rhythmclick/", "d": "踩准节拍点击，越准分越高。"}, {"t": "记忆序列", "u": "/more/games/simon/", "d": "看清闪烁顺序，按顺序复现。"}, {"t": "猜词", "u": "/more/games/wordle/", "d": "六次机会猜出四字词，颜色给提示。"}, {"t": "成语接龙", "u": "/more/games/idiom/", "d": "下一个成语的第一个字接上一个的末字。"}, {"t": "元素配对", "u": "/more/games/elements/", "d": "把元素符号和中文名配对。"}, {"t": "谐音梗猜词", "u": "/more/games/homophone/", "d": "给一句谐音梗，猜对应的词。"}, {"t": "魔方计时器", "u": "/more/games/cubetimer/", "d": "按空格开始/停止，记录你的复原时间。"}, {"t": "图片拼图", "u": "/more/games/picpuzzle/", "d": "把打乱的图块拖回原位。"}, {"t": "弹球", "u": "/more/games/pinball/", "d": "用挡板把球弹回去，别让它落下。"}, {"t": "打地鼠", "u": "/more/games/whack/", "d": "地鼠随机冒出，30 秒内尽量多打。"}, {"t": "赛车躲避", "u": "/more/games/racer/", "d": "左右移动躲开迎面而来的车。"}, {"t": "平台跳跃", "u": "/more/games/platformer/", "d": "三关，跳到终点旗子。"}, {"t": "极简塔防", "u": "/more/games/towerdefense/", "d": "在路径旁放塔，挡住一波波敌人。"}, {"t": "纸牌接龙", "u": "/more/games/solitaire/", "d": "经典 Klondike，把四种花色按顺序码好。"}, {"t": "工具", "u": "/more/tools/", "d": "更多 · 工具"}, {"t": "JVM 参数生成器", "u": "/more/tools/jvm/", "d": "按内存与人数给一组推荐参数。"}, {"t": "服务器状态", "u": "/more/tools/serverstatus/", "d": "输入地址查询在线人数与延迟。"}, {"t": "KubeJS 配方生成器", "u": "/more/tools/recipe/", "d": "填材料与产物，输出 KubeJS 脚本。"}, {"t": "崩溃报告解读器", "u": "/more/tools/crashreader/", "d": "粘贴崩溃报告，提取关键行与可能原因。"}, {"t": "资料库", "u": "/more/library/", "d": "更多 · 资料库"}, {"t": "技术笔记", "u": "/more/library/notes/", "d": "模组开发里踩过的坑与验证方法。"}, {"t": "术语表", "u": "/more/library/glossary/", "d": "模组生态里的常用词，中英对照。"}, {"t": "路线图", "u": "/more/library/roadmap/", "d": "接下来打算做什么（待补充）。"}, {"t": "壁纸下载", "u": "/more/library/wallpapers/", "d": "桌面与手机尺寸的站点壁纸。"}, {"t": "安装教程", "u": "/more/library/install/", "d": "从零把模组装进游戏。"}, {"t": "服主手册", "u": "/more/library/serverhandbook/", "d": "从开服到长期维护的清单。"}, {"t": "报错对照表", "u": "/more/library/errors/", "d": "常见报错关键词与处理方式。"}, {"t": "互动", "u": "/more/community/", "d": "更多 · 互动"}, {"t": "留言板", "u": "/more/community/guestbook/", "d": "留言通过 GitHub Issue 提交，列表读仓库数据。"}, {"t": "访客看板", "u": "/more/community/visitorpanel/", "d": "把站点访问数据做成一块小面板。"}, {"t": "友链", "u": "/more/community/friends/", "d": "交换链接的说明与位置。"}, {"t": "贡献者", "u": "/more/community/contributors/", "d": "测试、反馈、翻译过的人。"}, {"t": "作品墙", "u": "/more/community/gallery/", "d": "玩家投稿的截图与建筑。"}, {"t": "问卷", "u": "/more/community/survey/", "d": "想要什么模组，通过 Issue 告诉我们。"}, {"t": "反馈", "u": "/more/community/feedback/", "d": "报错与建议，走 GitHub Issue。"}, {"t": "招募", "u": "/more/community/recruiting/", "d": "在找的人与联系方式。"}, {"t": "邮件订阅", "u": "/more/community/subscribe/", "d": "通过 GitHub Watch 接收更新。"}, {"t": "RSS 订阅", "u": "/more/community/rss/", "d": "订阅文章与更新日志。"}, {"t": "展示", "u": "/more/showcase/", "d": "更多 · 展示"}, {"t": "动效实验室", "u": "/more/showcase/effects/", "d": "调玻璃材质、光斑与动效参数。"}, {"t": "设计系统", "u": "/more/showcase/design/", "d": "颜色、字号、间距与组件规范。"}, {"t": "排字样张", "u": "/more/showcase/typography/", "d": "标题、正文、代码的排版示例。"}, {"t": "图标集", "u": "/more/showcase/icons/", "d": "站内使用的线性图标。"}, {"t": "动效演示", "u": "/more/showcase/motion/", "d": "滚动、悬停、加载的动效样例。"}, {"t": "玻璃对比", "u": "/more/showcase/glasscompare/", "d": "玻璃材质与普通卡片的并排对比。"}, {"t": "排印细节", "u": "/more/showcase/typography2/", "d": "字距、行高、标点的处理方式。"}, {"t": "图标示例", "u": "/more/showcase/icons2/", "d": "站内图标的用法与尺寸。"}, {"t": "配色生成器", "u": "/more/showcase/palette/", "d": "上传一张图，提取主色与可用的强调色。"}, {"t": "组件状态", "u": "/more/showcase/states/", "d": "按钮、输入框、卡片的各种状态。"}, {"t": "空与错误状态", "u": "/more/showcase/emptyerror/", "d": "没有数据、加载失败时该长什么样。"}, {"t": "深浅对照", "u": "/more/showcase/themes/", "d": "暗色与亮色主题的对照表。"}, {"t": "移动端设计稿", "u": "/more/showcase/mobile/", "d": "窄屏下的布局取舍。"}, {"t": "设计决策记录", "u": "/more/showcase/decisions/", "d": "为什么这么选，以及放弃了什么。"}, {"t": "个性化", "u": "/more/personal/", "d": "更多 · 个性化"}, {"t": "鼠标轨迹", "u": "/more/personal/trail/", "d": "开启后鼠标后面会拖出霜点。"}, {"t": "随机模组", "u": "/more/personal/randommod/", "d": "从二十个模组里抽一个给你。"}, {"t": "昼夜主题", "u": "/more/personal/daynight/", "d": "在晨与夜之间切换配色。"}, {"t": "我该玩什么", "u": "/more/personal/whattoplay/", "d": "三个问题，推荐一个模组。"}, {"t": "主题编辑器", "u": "/more/personal/theme/", "d": "自选强调色，实时预览。"}, {"t": "字体与密度", "u": "/more/personal/a11y/", "d": "调整字号与布局密度。"}, {"t": "减少动效", "u": "/more/personal/motion/", "d": "关闭动画与光效，只保留必要反馈。"}, {"t": "界面语言", "u": "/more/personal/lang/", "d": "切换导航与常用文案的语言。"}, {"t": "布局密度", "u": "/more/personal/density/", "d": "在宽松与紧凑之间切换。"}, {"t": "首页", "u": "/", "d": ""}, {"t": "作品", "u": "/works/", "d": ""}, {"t": "Minecraft 模组", "u": "/work/mcmod/", "d": ""}, {"t": "应用与工具", "u": "/work/normal/", "d": ""}, {"t": "关于", "u": "/about/", "d": ""}, {"t": "服务", "u": "/services/", "d": ""}, {"t": "团队", "u": "/team/", "d": ""}, {"t": "联系", "u": "/contact/", "d": ""}];
